+      .masthead p { font-size: 9px; letter-spacing: .1em; }
+      .hero-image { object-position: 73% center; }
+      .hero-content { padding: 100px 6% 32px; grid-template-columns: 1fr; gap: 30px; }
+      h1 { max-width: 6em; font-size: clamp(64px, 13vw, 91px); margin-bottom: 22px; }
+      .explore { width: 106px; padding: 14px; font-size: 13px; }
+      .hero-foot { margin-inline: 6%; font-size: 9px; letter-spacing: .09em; }
+      .work { padding: 56px 6% 28px; }
+      .section-heading { align-items: center; }
+      .section-heading span { font-size: 9px; }
+      figure { margin-top: 26px; }
+      figcaption { flex-direction: column; gap: 4px; }
+    }
+    @media (max-height: 540px) and (min-width: 701px) {
+      .hero { min-height: 540px; }
+      .hero-content { padding-top: 70px; }
