+      <img class="hero-image" src="assets/poster.svg" alt="" width="960" height="540" fetchpriority="high">
+      <header class="masthead">
+        <span class="mark" aria-hidden="true"></span>
+        <p>Independent film practice</p>
+      </header>
+      <div class="hero-content">
+        <div>
+          <h1 id="hero-title">A quiet study.</h1>
+          <p class="intro">An independent film practice.</p>
+        </div>
+        <a class="explore" href="#work"><span>Explore</span><span class="arrow" aria-hidden="true">↗</span></a>
+      </div>
+      <div class="hero-foot"><span>Image, form &amp; atmosphere</span><span>Poster / Still image</span></div>
+    </section>
+    <section class="work" id="work" aria-labelledby="work-title">
+      <div class="section-heading"><h2 id="work-title">Selected work</h2><span>A quiet study.</span></div>
+      <figure>
